//! 2x polyphase oversampler for bridging sub-96 kHz hosts to the 96 kHz model.
//!
//! The LSTM is trained at 96 kHz. When the host runs below 96 kHz the plugin
//! upsamples 2x, runs the model on each oversampled sample, then downsamples.
//!
//! Both directions use a single 63-tap windowed-sinc (Kaiser, beta = 8.6)
//! half-band low-pass FIR, generated by `tools/gen_fir_coeffs.py`. The FIR is
//! scaled x2 so that, applied to a zero-stuffed stream, its DC gain is unity
//! (a constant input yields a constant 2x output -> both interpolated phases
//! converge to the input value, satisfying `upsample_dc_returns_constant`).
//!
//! The 63-tap length meets the >= 80 dB stopband spec much closer to Nyquist
//! than the previous 31-tap design: rejection reaches ~80 dB by ~0.28 of the
//! 2x rate (the unscaled firwin response first crosses -80 dB at ~0.294
//! cycles/sample, vs ~0.340 for the 31-tap). Near base-Nyquist the 31-tap only
//! achieved ~6-13 dB, so this is a real fidelity upgrade.
//!
//! ## Polyphase upsampling
//! With the input samples sitting at even positions of the (implicit)
//! zero-stuffed stream, the two 2x output phases decompose into:
//!   - phase 0 (even output index): the even-indexed FIR taps (symmetric
//!     interpolating sub-filter, peak ~0.625 at the center);
//!   - phase 1 (odd output index): the odd-indexed FIR taps, which for a
//!     half-band design reduce to a pure delay (center odd tap ~= 1.0).
//!
//! ## Polyphase downsampling
//! The decimator is the same FIR at half gain (DC gain 1) applied to the 2x
//! stream, keeping one output per input. The interpolator already band-limited
//! the signal, so the cascade upsample -> downsample is a delayed identity.
//!
//! ## Group delay / latency
//! Each 63-tap pass has group delay (63-1)/2 = 31 at the 2x rate; the two
//! passes (interpolate then decimate) sum to 62 at the 2x rate = 31 base-rate
//! samples. As measured by the `upsample_then_downsample_is_unity_after_latency`
//! test, the cascade group delay centers on a half-integer between 31 and 32
//! base-rate samples (max_err is identical at either); we fold one extra
//! base-rate sample into the decimator history read (the same technique used
//! for the 31-tap version, which centered on 16) so the reported latency lands
//! on the upper integer 32. Hence `latency_samples()` reports 32.
//!
//! All state is fixed-size arrays + a `usize` index (ring buffers); no `Vec`,
//! `Box`, or any heap allocation in `upsample`/`downsample`.

const N: usize = 63;

// Pasted verbatim from `tools/gen_fir_coeffs.py` (10 significant digits). Some
// near-zero half-band taps carry more precision than f32 can represent; that is
// harmless (they round to the same f32) so we keep the exact generator output.
#[allow(clippy::excessive_precision)]
const COEFFS: [f32; N] = [
    -2.7364620685e-05,
    3.9112619370e-19,
    1.4735964956e-04,
    -4.5038590649e-19,
    -4.3184131143e-04,
    -1.3148348088e-18,
    9.9747418015e-04,
    -2.1071060505e-18,
    -2.0040451704e-03,
    1.3404860470e-17,
    3.6601092542e-03,
    -5.8928080617e-18,
    -6.2299825022e-03,
    8.7715525155e-18,
    1.0046578840e-02,
    -1.2297010516e-17,
    -1.5539858360e-02,
    1.6365686609e-17,
    2.3302289347e-02,
    -2.0793244492e-17,
    -3.4242258580e-02,
    2.5324350189e-17,
    4.9963824539e-02,
    -2.9654204738e-17,
    -7.3822772894e-02,
    3.3459566210e-17,
    1.1454226430e-01,
    -3.6435230365e-17,
    -2.0430706388e-01,
    3.8330725554e-17,
    6.3394618122e-01,
    9.9999821198e-01,
    6.3394618122e-01,
    3.8330725554e-17,
    -2.0430706388e-01,
    -3.6435230365e-17,
    1.1454226430e-01,
    3.3459566210e-17,
    -7.3822772894e-02,
    -2.9654204738e-17,
    4.9963824539e-02,
    2.5324350189e-17,
    -3.4242258580e-02,
    -2.0793244492e-17,
    2.3302289347e-02,
    1.6365686609e-17,
    -1.5539858360e-02,
    -1.2297010516e-17,
    1.0046578840e-02,
    8.7715525155e-18,
    -6.2299825022e-03,
    -5.8928080617e-18,
    3.6601092542e-03,
    1.3404860470e-17,
    -2.0040451704e-03,
    -2.1071060505e-18,
    9.9747418015e-04,
    -1.3148348088e-18,
    -4.3184131143e-04,
    -4.5038590649e-19,
    1.4735964956e-04,
    3.9112619370e-19,
    -2.7364620685e-05,
];

/// Number of input samples in the interpolator delay line. Covers the
/// even-indexed taps (indices 0,2,..,62 -> 32 taps) and odd-indexed taps
/// (1,3,..,61 -> 31 taps); (N+1)/2 = 32 entries is enough for both phases.
const UP_HIST: usize = N.div_ceil(2);

/// Length of the 2x-rate decimator delay line. It must hold the full FIR
/// support (63 taps) plus 2 extra 2x-rate samples (= 1 base-rate sample) so the
/// cascade group delay lands on exactly 32 base-rate samples.
const DOWN_HIST: usize = N + 2;

pub struct Oversample2x {
    /// Ring buffer of the most recent base-rate input samples (newest first
    /// when read via `up_idx`). Used by both upsample phases.
    up_buf: [f32; UP_HIST],
    up_idx: usize,
    /// Ring buffer of the most recent 2x-rate samples fed to `downsample`.
    down_buf: [f32; DOWN_HIST],
    down_idx: usize,
}

impl Oversample2x {
    pub const fn new() -> Self {
        Self {
            up_buf: [0.0; UP_HIST],
            up_idx: 0,
            down_buf: [0.0; DOWN_HIST],
            down_idx: 0,
        }
    }

    /// Upsample one base-rate sample to two 2x-rate samples (phase 0, phase 1).
    pub fn upsample(&mut self, x: f32) -> (f32, f32) {
        // Push newest input into the ring buffer.
        self.up_idx = (self.up_idx + UP_HIST - 1) % UP_HIST;
        self.up_buf[self.up_idx] = x;

        // Polyphase convolution. tap j of a phase reads input (j) samples back.
        let mut phase0 = 0.0f32; // even-indexed FIR taps: COEFFS[2*j]
        let mut phase1 = 0.0f32; // odd-indexed FIR taps:  COEFFS[2*j+1]
        let mut j = 0usize;
        while j < UP_HIST {
            let xj = self.up_buf[(self.up_idx + j) % UP_HIST];
            phase0 += COEFFS[2 * j] * xj;
            if 2 * j + 1 < N {
                phase1 += COEFFS[2 * j + 1] * xj;
            }
            j += 1;
        }
        (phase0, phase1)
    }

    /// Downsample two 2x-rate samples back to one base-rate sample.
    pub fn downsample(&mut self, y0: f32, y1: f32) -> f32 {
        // Push the two 2x-rate samples (phase 0 then phase 1) into the ring.
        self.down_idx = (self.down_idx + DOWN_HIST - 1) % DOWN_HIST;
        self.down_buf[self.down_idx] = y1;
        self.down_idx = (self.down_idx + DOWN_HIST - 1) % DOWN_HIST;
        self.down_buf[self.down_idx] = y0;

        // Half-band decimation at DC gain 1 (COEFFS has DC gain 2). The read is
        // offset by 2 extra 2x-rate samples (= 1 base-rate sample) so the
        // cascade group delay is exactly 32 base-rate samples.
        let mut acc = 0.0f32;
        let mut k = 0usize;
        while k < N {
            let v = self.down_buf[(self.down_idx + 2 + k) % DOWN_HIST];
            acc += COEFFS[k] * v;
            k += 1;
        }
        acc * 0.5
    }

    pub fn reset(&mut self) {
        self.up_buf = [0.0; UP_HIST];
        self.up_idx = 0;
        self.down_buf = [0.0; DOWN_HIST];
        self.down_idx = 0;
    }
}

impl Default for Oversample2x {
    fn default() -> Self {
        Self::new()
    }
}

/// Bridges a host running at ~2x the model's native rate down to the model rate and back, so the
/// 48 kHz-trained model is evaluated near 48 kHz on 88.2/96 kHz hosts. It reuses the half-band FIRs
/// in the opposite order to [`Oversample2x`]: each host sample PAIR is anti-alias-decimated to ONE
/// model sample, the model runs once, and the result is interpolated back to a host PAIR.
///
/// The per-sample contract is 1-in-1-out: `process` takes one host sample and returns one host
/// sample, buffering internally so the model runs once per two calls. The first output of a pair is
/// returned on the odd call; the second is held and returned on the following even call (one extra
/// host-sample of delay folded into the reported latency).
///
/// All state is fixed-size; no heap allocation in `process`.
pub struct HostBridge {
    os: Oversample2x,
    /// Even/odd phase across host samples (false = first of a pair).
    odd: bool,
    /// First host sample of the current pair, awaiting its partner.
    x0: f32,
    /// Second interpolator output, held to emit on the next (even) call.
    held: f32,
}

/// Reported latency of the [`HostBridge`] cascade, in HOST-rate samples. Measured by
/// `host_bridge_step_latency` (impulse/step alignment of the decimate->interp cascade plus the
/// one-sample inter-pair hold).
pub const HOST_BRIDGE_LATENCY: usize = 64;

impl HostBridge {
    pub const fn new() -> Self {
        Self {
            os: Oversample2x::new(),
            odd: false,
            x0: 0.0,
            held: 0.0,
        }
    }

    /// Run one host sample through decimate -> `model` -> interpolate. `model` is evaluated once per
    /// two calls (on the odd call); the even call returns the held second output of the prior pair.
    #[inline]
    pub fn process<F: FnMut(f32) -> f32>(&mut self, x: f32, mut model: F) -> f32 {
        if !self.odd {
            // First of a pair: stash the input, emit the previously-held second output.
            self.x0 = x;
            self.odd = true;
            self.held
        } else {
            // Second of a pair: decimate the pair to one model sample, run the model, interpolate
            // back to two host samples. Emit the first now, hold the second for the next even call.
            self.odd = false;
            let lo = self.os.downsample(self.x0, x);
            let m = model(lo);
            let (o0, o1) = self.os.upsample(m);
            self.held = o1;
            o0
        }
    }

    pub fn reset(&mut self) {
        self.os.reset();
        self.odd = false;
        self.x0 = 0.0;
        self.held = 0.0;
    }
}

impl Default for HostBridge {
    fn default() -> Self {
        Self::new()
    }
}

// ===========================================================================
// General rational sample-rate-conversion bridge (`SrcBridge`)
// ===========================================================================
//
// `HostBridge` above only pins the model to its native rate at the exact 2:1
// ratio (88.2/96 kHz hosts). `SrcBridge` generalises that to an EXACT rational
// resampler so the model is evaluated at its native rate `model_sr` for ANY host
// rate: 44.1, 64, 176.4, 192 kHz, etc. Real hosts only ever report rates that are
// exact rationals of 48 kHz, so a rational `L/M` polyphase has zero
// fractional-interpolation error (strictly better than a fractional-sinc design).
//
// Architecture (per host sample, side-effecting `model()` clocked in the middle):
//
//   host_in (host_sr) → [in_stage: host→model] → model() → [out_stage: model→host] → host_out
//
// `in_stage` emits exactly `L_in` model samples per `M_in` host samples
// (`L_in/M_in = model_sr/host_sr`); `out_stage` emits exactly one host sample per
// `process` call (the 1-in-1-out contract the per-sample driver in `lib.rs` needs),
// pulling model samples from `mbuf` as its own polyphase phase advances. A fixed
// priming offset (run the input side forward on leading zeros at `prepare`) keeps
// the consumer from ever starving and makes the latency a fixed integer, measured
// empirically from the cascade's impulse response.
//
// All rings/banks are `Vec` allocated ONCE in `prepare` (init-time); `process` only
// indexes them — zero heap allocation on the audio thread.

/// Base taps-per-output for each polyphase phase in the non-decimating direction.
const SRC_Q: usize = 16;
/// Hard cap on the polyphase phase count `L` (= `model_sr / gcd`). 256 covers the
/// worst common case 44.1↔48 kHz (`L = 160`). Exotic host rates whose reduced `L`
/// exceeds this are approximated by the nearest rational with `L ≤ SRC_L_MAX`.
const SRC_L_MAX: u32 = 256;
/// Cap on taps-per-phase after the decimation scale-up (`Q * ceil(Fin/Fout)`).
/// 4× (192→48) is the worst common decimation; 128 leaves headroom.
const SRC_MAX_TAPS: usize = 128;
/// Power-of-two ring capacity for the host-input and model history buffers. Must
/// exceed `SRC_MAX_TAPS` plus the priming lead.
const SRC_RING: usize = 512;
const SRC_RING_MASK: usize = SRC_RING - 1;

#[inline]
fn gcd_u32(a: u32, b: u32) -> u32 {
    let (mut a, mut b) = (a, b);
    while b != 0 {
        let t = a % b;
        a = b;
        b = t;
    }
    a
}

/// Zeroth-order modified Bessel function I0, series form (enough terms for β≈8.6).
fn bessel_i0(x: f64) -> f64 {
    let mut sum = 1.0;
    let mut term = 1.0;
    let half_x = x * 0.5;
    let mut k = 1.0;
    // ~30 terms is plenty for the argument range here.
    while k < 30.0 {
        term *= (half_x / k) * (half_x / k);
        sum += term;
        if term < 1e-12 * sum {
            break;
        }
        k += 1.0;
    }
    sum
}

#[inline]
fn sinc(x: f64) -> f64 {
    if x.abs() < 1e-9 {
        1.0
    } else {
        let p = std::f64::consts::PI * x;
        p.sin() / p
    }
}

/// Best rational approximation `L/M` of `num/den` with `L ≤ max_l`, via a bounded
/// continued-fraction (Stern–Brocot) expansion. Returns the reduced `(L, M)`.
/// Exact when `den/gcd ≤ max_l` (every standard host rate vs 48 kHz).
fn rational_approx(num: u32, den: u32, max_l: u32) -> (u32, u32) {
    let g = gcd_u32(num, den);
    let (l0, m0) = (num / g, den / g);
    if l0 <= max_l {
        return (l0, m0);
    }
    // Continued-fraction convergents of l0/m0, keep the last with L ≤ max_l.
    let (mut a, mut b) = (l0 as u64, m0 as u64);
    let (mut h0, mut h1) = (0u64, 1u64); // numerators (→ L)
    let (mut k0, mut k1) = (1u64, 0u64); // denominators (→ M)
    let (mut best_l, mut best_m) = (1u32, 1u32);
    while b != 0 {
        let q = a / b;
        let h2 = q * h1 + h0;
        let k2 = q * k1 + k0;
        if h2 > max_l as u64 {
            break;
        }
        best_l = h2 as u32;
        best_m = k2.max(1) as u32;
        h0 = h1;
        h1 = h2;
        k0 = k1;
        k1 = k2;
        let r = a % b;
        a = b;
        b = r;
    }
    (best_l.max(1), best_m.max(1))
}

/// One exact-rational polyphase stage. Pure resampling math + an output counter;
/// the history ring it convolves is owned by [`SrcBridge`] and passed in, so the
/// same type serves both the host→model and model→host directions.
struct PolyStage {
    l: i64,
    m: i64,
    taps: usize,
    half: i64,
    /// `l * taps`, phase-major: `bank[phase*taps + t]`.
    bank: Vec<f32>,
    /// Next output index to produce.
    out_k: i64,
}

impl PolyStage {
    fn empty() -> Self {
        Self { l: 1, m: 1, taps: 0, half: 0, bank: Vec::new(), out_k: 0 }
    }

    /// Build the `L`-phase windowed-sinc bank for converting `fin → fout`.
    fn prepare(&mut self, fin: u32, fout: u32) {
        let (l, m) = rational_approx(fout, fin, SRC_L_MAX);
        self.l = l as i64;
        self.m = m as i64;
        // Decimation (fin > fout) widens the kernel: scale the tap count by ⌈M/L⌉.
        let scale = if m > l { m.div_ceil(l) as usize } else { 1 };
        let mut taps = (SRC_Q * scale).min(SRC_MAX_TAPS);
        if taps % 2 != 0 {
            taps += 1;
        }
        self.taps = taps;
        self.half = (taps / 2) as i64;
        // Low-pass cutoff at the LOWER Nyquist (cycles per input sample). For
        // upsampling (L>M) this caps at the input Nyquist (0.5); for decimation it
        // is 0.5·L/M. A 0.90 rolloff leaves a transition band inside Nyquist.
        let lp = (l as f64 / m as f64).min(1.0);
        let fc = 0.5 * lp * 0.90;
        let beta = 8.6_f64;
        let i0_beta = bessel_i0(beta);
        let half_f = self.half as f64;
        let mut bank = vec![0.0f32; l as usize * taps];
        for phase in 0..l as usize {
            let frac = phase as f64 / l as f64;
            // First pass: raw windowed-sinc; second: normalise the phase to unity DC.
            let mut sum = 0.0f64;
            let base = phase * taps;
            for t in 0..taps {
                // Continuous filter argument: distance (in input samples) from the
                // output position (base+frac) to input index (base-half+1+t).
                let x = frac + half_f - 1.0 - t as f64;
                let w = if x.abs() >= half_f {
                    0.0
                } else {
                    bessel_i0(beta * (1.0 - (x / half_f).powi(2)).max(0.0).sqrt()) / i0_beta
                };
                let h = 2.0 * fc * sinc(2.0 * fc * x) * w;
                bank[base + t] = h as f32;
                sum += h;
            }
            if sum.abs() > 1e-12 {
                let inv = 1.0 / sum;
                for t in 0..taps {
                    bank[base + t] = (bank[base + t] as f64 * inv) as f32;
                }
            }
        }
        self.bank = bank;
        self.out_k = 0;
    }

    /// Integer base position (in input samples) of output `out_k`.
    #[inline]
    fn base(&self, k: i64) -> i64 {
        (k * self.m).div_euclid(self.l)
    }

    /// Can output `self.out_k` be computed given `in_count` inputs have been written?
    /// (The kernel reads input indices up to `base + half`.)
    #[inline]
    fn can_emit(&self, in_count: i64) -> bool {
        self.base(self.out_k) + self.half < in_count
    }

    /// Compute the next output sample from `ring` (absolute-index, power-of-two
    /// masked). Negative indices read as 0 (pre-history silence). Advances `out_k`.
    #[inline]
    fn compute(&mut self, ring: &[f32], mask: usize) -> f32 {
        let k = self.out_k;
        let base = self.base(k);
        let phase = (k * self.m).rem_euclid(self.l) as usize;
        let row = phase * self.taps;
        let mut acc = 0.0f32;
        for t in 0..self.taps {
            let j = base - self.half + 1 + t as i64;
            let s = if j < 0 { 0.0 } else { ring[(j as usize) & mask] };
            acc += self.bank[row + t] * s;
        }
        self.out_k += 1;
        acc
    }
}

/// General rational SRC bridge. Pins the model to its native rate for any host SR.
pub struct SrcBridge {
    bypass: bool,
    in_stage: PolyStage,  // host → model
    out_stage: PolyStage, // model → host
    /// Host-input history ring (absolute index `hcount`, masked).
    hbuf: Vec<f32>,
    hcount: i64,
    /// Model-output history ring (absolute index `mcount`, masked).
    mbuf: Vec<f32>,
    mcount: i64,
    latency_host: usize,
}

impl SrcBridge {
    pub fn new() -> Self {
        Self {
            bypass: true,
            in_stage: PolyStage::empty(),
            out_stage: PolyStage::empty(),
            hbuf: Vec::new(),
            mbuf: Vec::new(),
            hcount: 0,
            mcount: 0,
            latency_host: 0,
        }
    }

    /// Configure for a `host_sr → model_sr → host_sr` round trip. Allocates the
    /// polyphase banks + history rings (init-time only). When `host_sr == model_sr`
    /// the bridge is a bit-exact passthrough (latency 0).
    pub fn prepare(&mut self, host_sr: u32, model_sr: u32) {
        if host_sr == model_sr || host_sr == 0 || model_sr == 0 {
            self.bypass = true;
            self.latency_host = 0;
            // Keep buffers sized so `reset` never allocates even in the bypass case.
            if self.hbuf.is_empty() {
                self.hbuf = vec![0.0; SRC_RING];
                self.mbuf = vec![0.0; SRC_RING];
            }
            self.hcount = 0;
            self.mcount = 0;
            return;
        }
        self.bypass = false;
        self.in_stage.prepare(host_sr, model_sr);
        self.out_stage.prepare(model_sr, host_sr);
        self.hbuf = vec![0.0; SRC_RING];
        self.mbuf = vec![0.0; SRC_RING];
        self.prime();
        self.latency_host = self.measure_latency();
        self.prime(); // clear the measurement impulse; leave primed/steady for real use
    }

    /// Run the input side forward on leading zeros until the model ring holds enough
    /// samples for `out_stage`'s first output, without advancing `out_stage`. Leaves
    /// the cascade in the primed steady state (output counter at 0).
    fn prime(&mut self) {
        self.hbuf.iter_mut().for_each(|s| *s = 0.0);
        self.mbuf.iter_mut().for_each(|s| *s = 0.0);
        self.hcount = 0;
        self.mcount = 0;
        self.in_stage.out_k = 0;
        self.out_stage.out_k = 0;
        // Target: enough model samples that out_stage k=0 (base 0) can read up to
        // `half`, plus a margin covering the per-output model consumption.
        let per_out = self.out_stage.m.div_euclid(self.out_stage.l).max(0);
        let target = self.out_stage.half + per_out + 4;
        let mut guard = 0;
        while self.mcount <= target && guard < SRC_RING as i64 {
            self.hbuf[(self.hcount as usize) & SRC_RING_MASK] = 0.0;
            self.hcount += 1;
            while self.in_stage.can_emit(self.hcount) {
                let lo = self.in_stage.compute(&self.hbuf, SRC_RING_MASK);
                self.mbuf[(self.mcount as usize) & SRC_RING_MASK] = lo;
                self.mcount += 1;
            }
            guard += 1;
        }
    }

    /// Measure the cascade group delay (host samples) from its impulse response:
    /// the argmax of |output| after a unit impulse, with an identity model.
    fn measure_latency(&mut self) -> usize {
        let n = SRC_MAX_TAPS * 4;
        let mut peak = 0.0f32;
        let mut peak_i = 0usize;
        for i in 0..n {
            let x = if i == 0 { 1.0 } else { 0.0 };
            let y = self.process(x, |lo| lo);
            if y.abs() > peak {
                peak = y.abs();
                peak_i = i;
            }
        }
        peak_i
    }

    #[inline]
    pub fn latency_host(&self) -> usize {
        self.latency_host
    }

    /// One host sample in, one host sample out. `model` is evaluated once per model
    /// sample the input side produces (0, 1, or more per call); its side effects
    /// (the net advancing its state) fire exactly the right number of times.
    #[inline]
    pub fn process<F: FnMut(f32) -> f32>(&mut self, x: f32, mut model: F) -> f32 {
        if self.bypass {
            return model(x);
        }
        self.hbuf[(self.hcount as usize) & SRC_RING_MASK] = x;
        self.hcount += 1;
        while self.in_stage.can_emit(self.hcount) {
            let lo = self.in_stage.compute(&self.hbuf, SRC_RING_MASK);
            let mo = model(lo);
            self.mbuf[(self.mcount as usize) & SRC_RING_MASK] = mo;
            self.mcount += 1;
        }
        debug_assert!(
            self.out_stage.can_emit(self.mcount),
            "SrcBridge consumer starved: mcount={} need>{}",
            self.mcount,
            self.out_stage.base(self.out_stage.out_k) + self.out_stage.half
        );
        self.out_stage.compute(&self.mbuf, SRC_RING_MASK)
    }

    pub fn reset(&mut self) {
        if self.bypass {
            self.hcount = 0;
            self.mcount = 0;
            return;
        }
        self.prime();
    }
}

impl Default for SrcBridge {
    fn default() -> Self {
        Self::new()
    }
}
